      const requiresAn = this.articleAn.has(lower) || this.articleAn.has(core);
      if (requiresA && !requiresAn) return `a ${lowerFirstIfCapitalized(value)}`;
      if (requiresAn && !requiresA) return `an ${lowerFirstIfCapitalized(value)}`;
      if (requiresA && requiresAn) return `a ${lowerFirstIfCapitalized(value)}`;
