        ruleId: "CA_SIMPLE_REPLACE_MULTIWORDS",
        category: "grammar",
        severity: "warning",
        message: entry.message || "Expressió incorrecta.",
        text: matchedText,
        start: from,
        end: to,
        replacementStart: from,
        replacementEnd: to,
        suggestions: finalSuggestions,
        rule: "CA_SIMPLE_REPLACE_MULTIWORDS",
        _ruleId: "CA_SIMPLE_REPLACE_MULTIWORDS",
