        ruleId: "SOFTCATALA_SPELLING_DIAGNOSTIC",
        category: "spelling",
        severity: "warning",
        message: "Possible error ortogràfic.",
        text: text.slice(token.start, token.end),
        start: token.start,
        end: token.end,
